import { ref } from 'vue';

export default {
  name: 'ParentComponent',
  setup() {
    const inputRef = ref(null);
    // Create click handler here
    return { inputRef };
  },
  template: `
    <div>
      <ChildComponent :forwardedRef="inputRef" />
      <button @click="handleFocus">Focus Input</button>
    </div>
  `
};

export default {
  name: 'ChildComponent',
  props: {
    forwardedRef: {
      type: Object,
      required: true
    }
  },
  template: `
    <div>
      <input :ref="forwardedRef" />
    </div>
  `
};
